    this.bulkRedateResult.set(null);
    this.bulkRedateError.set(null);
    const date = this.bulkRedateDate().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.bulkRedateError.set('Pick the date to re-date the selected claims to.');
      return;
